// 1. Le port, défini côté métier : une abstraction, pas un détail
interface OrderRepository {
    Order findById(UUID id);
}

// 2. Le use case dépend de l'abstraction, injectée au constructeur (final)
class GetOrder {
    private final OrderRepository repo;
    GetOrder(OrderRepository repo) {   // injection par constructeur
        this.repo = repo;
    }
    Order findOrder(UUID id) {
        return repo.findById(id);       // aucun new ici : plus de dépendance concrète
    }
}

// 3. Le détail technique réalise le port, côté adaptateur
class PostgresOrderRepository implements OrderRepository {
    public Order findById(UUID id) { /* accès base Postgres */ return null; }
}

// 4. Câblage à la main (sans conteneur IoC) : on FOURNIT l'implémentation
var useCase = new GetOrder(new PostgresOrderRepository());
// La dépendance de code pointe désormais du détail (Postgres) vers l'abstraction (le port).
// En test, on passe un faux repository : new GetOrder(fakeRepo).
